// Demand forecasting and anomaly detection (SP-MATH-006, SP-AI-002/003).
//
// Deterministic baselines first, as the research plan requires: seasonal
// naïve (same hour, same weekday type, last week), a moving average of the
// same hour over the previous n days, and Holt–Winters-style exponential
// smoothing of the hourly profile. They are evaluated on held-out days of a
// synthetic history generated by the facility's own arrival and stay models
// (28 days, weekday and weekend profiles, seeded). A machine-learning
// forecaster is planned only once real occupancy data exists; none runs here.
// Anomaly detection is rule-based and robust-statistical (median and MAD),
// labelled as such — not a trained model.
import { createRng } from "../math";
import { arrivals } from "./queueing";

export interface History {
  /** Occupied bays per hour, for each day (index 0 = oldest). */
  occupancy: number[][];
  /** Charging sessions started per hour. */
  charging: number[][];
  weekend: boolean[];
}

/** A synthetic history: commuter weekdays, softer weekends, seeded. */
export function syntheticHistory(bays: number, days: number, seed: number, evShare = 0.45, wirelessShare = 0.6): History {
  const r = createRng(seed);
  const occupancy: number[][] = [];
  const charging: number[][] = [];
  const weekend: boolean[] = [];
  for (let d = 0; d < days; d++) {
    const we = d % 7 >= 5;
    weekend.push(we);
    const rate = ((we ? 0.55 : 1) * bays * 1.3) / (24 * 3600) * 2.2;
    const times = arrivals(rate, 0, 24 * 3600, we ? "retail" : "commuter", 0, r);
    const occ = new Array(24).fill(0);
    const chg = new Array(24).fill(0);
    const leaving: number[] = [];
    for (const t of times) {
      for (let k = leaving.length - 1; k >= 0; k--) if (leaving[k] <= t) leaving.splice(k, 1);
      if (leaving.length >= bays) continue;
      const stay = Math.exp(Math.log((we ? 1.8 : 3.2) * 3600) - 0.25 + 0.7 * r.normal());
      leaving.push(t + stay);
      if (r.next() < evShare * wirelessShare * 0.85) chg[Math.floor(t / 3600)] += 1;
      for (let h = Math.floor(t / 3600); h < Math.min(24, Math.ceil((t + stay) / 3600)); h++) occ[h] += 1;
    }
    occupancy.push(occ.map((x) => Math.min(bays, x)));
    charging.push(chg);
  }
  return { occupancy, charging, weekend };
}

export type ForecastMethod = "seasonal-naive" | "moving-average" | "exp-smoothing";

export const FORECAST_INFO: Record<ForecastMethod, string> = {
  "seasonal-naive": "Same hour on the most recent day of the same type (weekday or weekend).",
  "moving-average": "Mean of the same hour over the last 4 days of the same type.",
  "exp-smoothing": "Exponentially smoothed hourly profile per day type (α = 0.3).",
};

/** Forecast of day `d` from days before it. */
export function forecastDay(h: History, d: number, method: ForecastMethod, series: "occupancy" | "charging" = "occupancy"): number[] {
  const data = h[series];
  const same = [...Array(d).keys()].filter((k) => h.weekend[k] === h.weekend[d]);
  if (!same.length) return new Array(24).fill(0);
  if (method === "seasonal-naive") return [...data[same[same.length - 1]]];
  if (method === "moving-average") {
    const last = same.slice(-4);
    return [...Array(24).keys()].map((hr) => last.reduce((a, k) => a + data[k][hr], 0) / last.length);
  }
  let level = [...data[same[0]]];
  for (const k of same.slice(1)) level = level.map((v, hr) => 0.3 * data[k][hr] + 0.7 * v);
  return level;
}

export interface ForecastScore {
  method: ForecastMethod;
  mae: number;
  rmse: number;
  /** Mean absolute error as a share of the bays. */
  maePct: number;
}

/** Scores each method on the last `test` days (rolling origin: each test day forecast from the days before it). */
export function evaluateForecasts(h: History, bays: number, test = 7, series: "occupancy" | "charging" = "occupancy"): ForecastScore[] {
  const n = h.occupancy.length;
  return (["seasonal-naive", "moving-average", "exp-smoothing"] as ForecastMethod[]).map((method) => {
    let abs = 0;
    let sq = 0;
    let count = 0;
    for (let d = n - test; d < n; d++) {
      const f = forecastDay(h, d, method, series);
      for (let hr = 0; hr < 24; hr++) {
        const e = f[hr] - h[series][d][hr];
        abs += Math.abs(e);
        sq += e * e;
        count += 1;
      }
    }
    return { method, mae: abs / count, rmse: Math.sqrt(sq / count), maePct: (abs / count / bays) * 100 };
  });
}

// ── Anomaly detection ─────────────────────────────────────────────────────

export const median = (xs: readonly number[]) => {
  if (!xs.length) return 0;
  const s = [...xs].sort((a, b) => a - b);
  const m = s.length >> 1;
  return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2;
};

/** Robust z-score: (x − median) / (1.4826 · MAD). */
export function robustZ(x: number, sample: readonly number[]): number {
  const m = median(sample);
  const mad = median(sample.map((v) => Math.abs(v - m))) * 1.4826;
  return mad > 1e-9 ? (x - m) / mad : 0;
}

export type AnomalyKind = "sensor-disagreement" | "unusual-duration" | "unexpected-occupancy" | "missing-occupancy" | "message-pattern" | "device-malfunction" | "energy-consumption" | "stale-data";

export interface Anomaly {
  id: string;
  kind: AnomalyKind;
  ref: string;
  t: number;
  text: string;
  score: number;
  method: "rule" | "robust-statistics";
}

export const ANOMALY_INFO: Record<AnomalyKind, string> = {
  "sensor-disagreement": "Fresh sensors of one bay disagree (rule).",
  "unusual-duration": "Stay longer than median + 3.5 robust deviations of recent stays (robust statistics).",
  "unexpected-occupancy": "A bay reads occupied with no session in it (rule).",
  "missing-occupancy": "A parked session's bay reads vacant (rule).",
  "message-pattern": "A device's message rate departs from its schedule: silent or flooding (rule).",
  "device-malfunction": "A sensor reports a constant raw value (stuck) or out of range (rule).",
  "energy-consumption": "Facility load departs from its expected value by more than 3.5 robust deviations (robust statistics).",
  "stale-data": "A device's latest state is older than the freshness limit (rule).",
};
